package org.telegram.ui.Components;

import android.app.Activity;
import android.content.*;
import android.graphics.Bitmap;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.Callable;
import org.json.JSONObject;
import org.telegram.messenger.*;
import org.telegram.ui.ActionBar.*;
import org.telegram.ui.Cells.*;

/** Image-guide settings and the account-local portable template library. */
public final class DevGramCanvasOverlayEditor {
    private static final int PHOTO=7691,IMPORT=7692,EXPORT=7693;
    private final BaseFragment host;private final DevGramPixelCanvasView canvas;private final long owner,viewer;private final String block;private final Theme.ResourcesProvider resources;
    private JSONObject settings=new JSONObject();private volatile int generation;private volatile boolean closed;private byte[] exporting;private BottomSheet sheet;private LinearLayout content;
    public DevGramCanvasOverlayEditor(BaseFragment host,DevGramPixelCanvasView canvas,long owner,long viewer,String block,Theme.ResourcesProvider resources){this.host=host;this.canvas=canvas;this.owner=owner;this.viewer=viewer;this.block=block;this.resources=resources;int request=++generation;Utilities.globalQueue.postRunnable(()->{DevGramCanvasOverlay model=DevGramCanvasOverlay.restore(ApplicationLoader.applicationContext,viewer,owner,block);AndroidUtilities.runOnUIThread(()->{if(valid()&&request==generation&&model!=null)accept(model);});});}
    private String t(String value){return DevGramLocale.text(value);}private boolean valid(){return !closed&&host.getUserConfig().getClientUserId()==viewer&&DevGramProfileCustomization.enabled()&&DevGramProfilePolicy.allowed(owner,"profile.blocks.pixels");}
    private void error(){if(valid()&&host.getParentActivity()!=null)Toast.makeText(host.getParentActivity(),t("Не удалось обработать шаблон"),Toast.LENGTH_SHORT).show();}
    private void accept(DevGramCanvasOverlay model){canvas.overlay(model);settings=DevGramProfileDocument.copy(model.settings);if(content!=null)fill();}
    private void change(String key,Object value){change(key,value,key.equals("side")||key.equals("colors")||key.equals("visible"),true);}
    private void change(String key,Object value,boolean refresh,boolean persist){if(!valid()||canvas.overlay()==null)return;try{settings.put(key,value);JSONObject next=DevGramProfileDocument.copy(settings);DevGramCanvasOverlay source=canvas.overlay();job(()->source.with(next),refresh,persist);}catch(Exception e){error();}}
    private void job(Callable<DevGramCanvasOverlay> work,boolean refresh){job(work,refresh,true);}
    private void job(Callable<DevGramCanvasOverlay> work,boolean refresh,boolean persist){int request=++generation;Utilities.globalQueue.postRunnable(()->{if(closed||request!=generation)return;try{DevGramCanvasOverlay result=work.call();if(closed||request!=generation)return;if(persist)result.persist(ApplicationLoader.applicationContext,viewer,owner,block);AndroidUtilities.runOnUIThread(()->{if(!valid()||request!=generation)return;canvas.overlay(result);settings=DevGramProfileDocument.copy(result.settings);if(refresh&&content!=null)fill();});}catch(Exception e){AndroidUtilities.runOnUIThread(this::error);}});}
    public void show(){if(!valid()||host.getParentActivity()==null)return;ScrollView scroll=new ScrollView(host.getParentActivity());content=DevGramStudioControls.column(host.getParentActivity());scroll.addView(content);sheet=new BottomSheet.Builder(host.getParentActivity(),false,resources).setTitle(t("Подложка для рисования")).setCustomView(scroll).create();sheet.fixNavigationBarKey(Theme.key_dialogBackground);fill();host.showDialog(sheet,d->{content=null;sheet=null;});}
    private void fill(){
        if(content==null||host.getParentActivity()==null)return;content.removeAllViews();DevGramCanvasOverlay model=canvas.overlay();
        TextView hint=DevGramStudioControls.text(host.getParentActivity(),"Подложка видна только вам. Она помогает рисовать по образцу и не отправляет пиксели автоматически.",13,false,resources);hint.setGravity(Gravity.CENTER);hint.setPadding(AndroidUtilities.dp(22),AndroidUtilities.dp(12),AndroidUtilities.dp(22),AndroidUtilities.dp(16));content.addView(hint);
        action("Выбрать изображение",true,()->pick(PHOTO,"image/*"),null);
        slider("Размер подложки","side",4,384," px");slider("Количество цветов","colors",2,64,"");slider("Непрозрачность","alpha",24,230,"/255");
        LinearLayout placement=new LinearLayout(host.getParentActivity());content.addView(placement);
        action("По центру",model!=null,()->{try{settings.put("x",canvas.centerX());}catch(Exception ignored){}change("y",canvas.centerY());},placement);
        action(settings.optBoolean("visible",true)?"Скрыть подложку":"Показать подложку",model!=null,()->change("visible",!settings.optBoolean("visible",true)),placement);
        LinearLayout library=new LinearLayout(host.getParentActivity());content.addView(library);action("Сохранить шаблон",model!=null,this::save,library);action("Библиотека шаблонов",true,()->{if(sheet!=null)sheet.dismiss();library(0);},library);
        action("Импортировать .cpbt",true,()->pick(IMPORT,"*/*"),null);
        TextView remove=action("Удалить подложку",model!=null,()->{int request=++generation;Utilities.globalQueue.postRunnable(()->{try{DevGramCanvasOverlay.clear(ApplicationLoader.applicationContext,viewer,owner,block);AndroidUtilities.runOnUIThread(()->{if(valid()&&request==generation){canvas.overlay(null);settings=new JSONObject();fill();}});}catch(Exception e){AndroidUtilities.runOnUIThread(this::error);}});},null);remove.setTextColor(Theme.getColor(Theme.key_text_RedRegular,resources));
    }
    private TextView action(String label,boolean enabled,Runnable click,LinearLayout parent){
        TextView button=DevGramStudioControls.text(host.getParentActivity(),label,14,true,resources);button.setGravity(Gravity.CENTER);button.setMaxLines(2);button.setPadding(AndroidUtilities.dp(8),0,AndroidUtilities.dp(8),0);int accent=Theme.getColor(Theme.key_windowBackgroundWhiteBlueText,resources);button.setTextColor(accent);button.setBackground(Theme.createSimpleSelectorRoundRectDrawable(AndroidUtilities.dp(12),androidx.core.graphics.ColorUtils.setAlphaComponent(accent,18),androidx.core.graphics.ColorUtils.setAlphaComponent(accent,38)));button.setEnabled(enabled);button.setAlpha(enabled?1:.4f);button.setOnClickListener(v->{if(valid()){DevGramStudioControls.haptic(v,HapticFeedbackConstants.KEYBOARD_TAP);click.run();}});LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(parent==null?-1:0,AndroidUtilities.dp(46),parent==null?0:1);params.setMargins(AndroidUtilities.dp(10),AndroidUtilities.dp(4),AndroidUtilities.dp(10),AndroidUtilities.dp(4));(parent==null?content:parent).addView(button,params);return button;
    }
    private void slider(String title,String key,int min,int max,String unit){DevGramStudioControls.Slider slider=new DevGramStudioControls.Slider(host.getParentActivity(),resources);final int[] selected={settings.optInt(key,key.equals("side")?32:key.equals("colors")?16:160)};slider.bind(t(title),selected[0],min,max,unit,canvas.overlay()!=null,value->{selected[0]=value;if(!key.equals("colors"))change(key,value,false,false);},()->change(key,selected[0]),null);content.addView(slider);}
    private void pick(int request,String mime){if(!valid())return;try{host.getParentActivity().startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType(mime).addCategory(Intent.CATEGORY_OPENABLE),request);}catch(Exception e){error();}}
    private void save(){DevGramCanvasOverlay model=canvas.overlay();if(model==null)return;EditText edit=new EditText(host.getParentActivity());edit.setSingleLine(true);edit.setHint(t("Название шаблона"));edit.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(80)});host.showDialog(new AlertDialog.Builder(host.getParentActivity(),resources).setTitle(t("Сохранить шаблон")).setView(edit).setPositiveButton(t("Сохранить"),(d,w)->{String name=edit.getText().toString().trim();if(name.isEmpty())name=t("Шаблон");String title=name;Utilities.globalQueue.postRunnable(()->{try{model.saveTemplate(ApplicationLoader.applicationContext,viewer,owner,block,title);AndroidUtilities.runOnUIThread(()->{if(valid())Toast.makeText(host.getParentActivity(),t("Шаблон сохранён"),Toast.LENGTH_SHORT).show();});}catch(Exception e){AndroidUtilities.runOnUIThread(this::error);}});}).setNegativeButton(DevGramLocale.getString(R.string.Cancel),null).create());}
    private static final class Entry{File file;String name;Bitmap preview;Entry(File file,DevGramCanvasOverlay model){this.file=file;name=model.settings.optString("name");preview=Bitmap.createScaledBitmap(model.pixels,96,96,false);}}
    public void library(int page){if(!valid())return;Utilities.globalQueue.postRunnable(()->{ArrayList<Entry> entries=new ArrayList<>();File[] files=DevGramCanvasOverlay.library(ApplicationLoader.applicationContext,viewer);for(int i=page*12;i<Math.min(files.length,(page+1)*12);i++)try(InputStream stream=new FileInputStream(files[i])){entries.add(new Entry(files[i],DevGramCanvasOverlay.unpack(stream)));}catch(Exception ignored){}AndroidUtilities.runOnUIThread(()->{if(!valid()||host.getParentActivity()==null)return;LinearLayout body=DevGramStudioControls.column(host.getParentActivity());BottomSheet[] library=new BottomSheet[1];for(Entry entry:entries){LinearLayout item=new LinearLayout(host.getParentActivity());item.setGravity(Gravity.CENTER_VERTICAL);item.setPadding(AndroidUtilities.dp(16),AndroidUtilities.dp(8),AndroidUtilities.dp(16),AndroidUtilities.dp(8));ImageView image=new ImageView(host.getParentActivity());image.setImageBitmap(entry.preview);image.setScaleType(ImageView.ScaleType.FIT_CENTER);item.addView(image,new LinearLayout.LayoutParams(AndroidUtilities.dp(64),AndroidUtilities.dp(64)));TextView title=DevGramStudioControls.text(host.getParentActivity(),entry.name.isEmpty()?"Шаблон":entry.name,15,true,resources);title.setPadding(AndroidUtilities.dp(14),0,0,0);item.addView(title,new LinearLayout.LayoutParams(0,-2,1));item.setBackground(Theme.createSelectorDrawable(Theme.getColor(Theme.key_listSelector,resources),2));item.setOnClickListener(v->host.showDialog(new AlertDialog.Builder(host.getParentActivity(),resources).setTitle(title.getText()).setItems(new String[]{t("Применить шаблон"),t("Экспортировать .cpbt"),t("Удалить")},(d,which)->{if(which<2){Utilities.globalQueue.postRunnable(()->{try(InputStream stream=new FileInputStream(entry.file)){DevGramCanvasOverlay model=DevGramCanvasOverlay.unpack(stream);AndroidUtilities.runOnUIThread(()->{if(!valid())return;if(which==0){library[0].dismiss();job(()->model,true);}else export(model);});}catch(Exception e){AndroidUtilities.runOnUIThread(this::error);}});}else host.showDialog(new AlertDialog.Builder(host.getParentActivity(),resources).setTitle(t("Удалить шаблон?")).setPositiveButton(t("Удалить"),(confirm,w)->{Utilities.globalQueue.postRunnable(()->{try{DevGramCanvasOverlay.deleteTemplate(ApplicationLoader.applicationContext,viewer,entry.file);AndroidUtilities.runOnUIThread(()->{if(valid()){library[0].dismiss();library(page);}});}catch(Exception e){AndroidUtilities.runOnUIThread(this::error);}});}).setNegativeButton(DevGramLocale.getString(R.string.Cancel),null).create());}).create()));body.addView(item);}if(entries.isEmpty()){TextView empty=DevGramStudioControls.text(host.getParentActivity(),"В библиотеке пока нет шаблонов. Сохраните подложку или импортируйте .cpbt.",14,false,resources);empty.setPadding(24,24,24,24);body.addView(empty);}if((page+1)*12<files.length){TextSettingsCell more=new TextSettingsCell(host.getParentActivity(),resources);more.setText(t("Далее"),false);more.setOnClickListener(v->{library[0].dismiss();library(page+1);});body.addView(more);}ScrollView scroll=new ScrollView(host.getParentActivity());scroll.addView(body);library[0]=new BottomSheet.Builder(host.getParentActivity(),false,resources).setTitle(t("Библиотека шаблонов")).setCustomView(scroll).create();library[0].fixNavigationBarKey(Theme.key_dialogBackground);host.showDialog(library[0]);});});}
    private void export(DevGramCanvasOverlay model){if(!valid())return;Utilities.globalQueue.postRunnable(()->{try{byte[] bytes=model.pack(model.settings.optString("name",t("Шаблон")),viewer,owner,block);AndroidUtilities.runOnUIThread(()->{if(!valid())return;exporting=bytes;try{host.getParentActivity().startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"DevGram-canvas.cpbt"),EXPORT);}catch(Exception e){exporting=null;error();}});}catch(Exception e){AndroidUtilities.runOnUIThread(this::error);}});}
    public void result(int request,int result,Intent data){if(result!=Activity.RESULT_OK||data==null||data.getData()==null||!valid()){if(request==EXPORT)exporting=null;return;}android.net.Uri uri=data.getData();if(request==PHOTO||request==IMPORT){int x=canvas.centerX(),y=canvas.centerY();job(()->{try(InputStream stream=ApplicationLoader.applicationContext.getContentResolver().openInputStream(uri)){DevGramCanvasOverlay model=request==PHOTO?DevGramCanvasOverlay.image(stream,x,y):DevGramCanvasOverlay.unpack(stream);if(request==IMPORT)model.saveTemplate(ApplicationLoader.applicationContext,viewer,owner,block,model.settings.optString("name",t("Шаблон")));return model;}},true);}else if(request==EXPORT&&exporting!=null){byte[] bytes=exporting;exporting=null;Utilities.globalQueue.postRunnable(()->{try(OutputStream stream=ApplicationLoader.applicationContext.getContentResolver().openOutputStream(uri)){if(stream==null)throw new IOException();stream.write(bytes);AndroidUtilities.runOnUIThread(()->{if(valid())Toast.makeText(host.getParentActivity(),t("Файл сохранён"),Toast.LENGTH_SHORT).show();});}catch(Exception e){AndroidUtilities.runOnUIThread(this::error);}});}}
    public void close(){closed=true;generation++;exporting=null;content=null;if(sheet!=null)sheet.dismiss();}
}
